def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    row_walls = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    col_walls = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def segments(n, walls):
        result, start = [], 0
        for wall in walls:
            if start < wall:
                result.append(list(range(start, wall)))
            start = wall + 1
        if start < n:
            result.append(list(range(start, n)))
        return result

    row_segments = segments(h, row_walls)
    col_segments = segments(w, col_walls)
    tiles = [(rs, cs) for rs in row_segments for cs in col_segments]

    # The tile with the most non-background cells supplies the repeating pattern.
    source_rs, source_cs = max(
        tiles,
        key=lambda t: sum(grid[r][c] != bg for r in t[0] for c in t[1])
    )
    out = [row[:] for row in grid]
    for rs in row_segments:
        for cs in col_segments:
            for i, r in enumerate(rs):
                for j, c in enumerate(cs):
                    out[r][c] = grid[source_rs[i % len(source_rs)]][source_cs[j % len(source_cs)]]
    return out
